mapper.select:
select o.goods_title as goodsTitle, a.patient_name as patientName, a.appointment_date as appointmentDate, a.status, r.file_url as fileUrl from med_exam_appointment a join trade_order o on a.order_id = o.order_id left join med_exam_report r on a.id = r.appointment_id where o.customer_id = #{customerId}
and (o.goods_title like concat('%',#{keyword},'%') or a.patient_name = #{keyword} or a.phone = #{keyword})
and a.appointment_date = #{appointmentDate}
and a.status = #{status}
order by a.appointment_date desc limit #{startIndex}, #{pageSize}

select count(*) from med_exam_appointment a join trade_order o on a.order_id = o.order_id where o.customer_id = #{customerId}
and (o.goods_title like concat('%',#{keyword},'%') or a.patient_name = #{keyword} or a.phone = #{keyword})
and a.appointment_date = #{appointmentDate}
and a.status = #{status}

SELECT a.id, a.patient_name as patientName, a.gender, CONCAT(SUBSTRING(a.phone,1,3),"****",SUBSTRING(a.phone,8,4)) AS phone, CONCAT(SUBSTRING(a.id_card_no,1,3),"***********",SUBSTRING(a.id_card_no,15,4)) AS idCardNo, TIMESTAMPDIFF(YEAR,a.birth_date,NOW()) AS age, a.company, a.status, o.goods_title AS goodsTitle, o.snapshot_id AS snapshotId FROM med_exam_appointment a JOIN trade_order o ON a.order_id = o.order_id
AND a.appointment_date = #{appointmentDate}
AND a.patient_name LIKE CONCAT("%",#{patientName},"%")
AND a.phone = #{phone}
AND a.status = #{status}
ORDER BY a.id DESC LIMIT #{startIndex}, #{pageSize}

